{
  "name": "sketchbook-demo",
  "title": "Sketchbook demo",
  "format": { "width": 1080, "height": 1920, "fps": 24, "bpm": 120, "duration": 6.0, "frames": 144 },
  "storyFormat": "morph chain (2 eras, 1 shape morph)",
  "style": "sketchbook",
  "review": { "safe": { "top": 240, "bottom": 420, "right": 140 }, "refs": {} }
}
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sketchbook demo</title>
<style>
  html, body { margin: 0; height: 100%; background: #1d1a17; overflow: hidden; }
  body { display: flex; align-items: center; justify-content: center; }
  canvas { height: min(100vh, calc(100vw * 16 / 9)); width: auto; aspect-ratio: 9 / 16; display: block; cursor: pointer; }
</style>
</head>
<body>
<canvas id="c" width="1080" height="1920"></canvas>
<script>
"use strict";
// =====================================================================
//  SKETCHBOOK DEMO — 9:16, 6.0s @ 120 BPM, 24fps. A puzzled doodle gets an idea: a lightbulb is pencilled in,
//  inked and scribbled yellow; the bulb becomes the sun over a sketched hill, and the hero waves from the top.
//  Proves the style kit renders, morphs and stays deterministic.
//  Build: node <skill>/tools/build.mjs <skill>/styles/sketchbook/demo
// =====================================================================
const FPS = 24, W = 1080, H = 1920;
const BPM = 120, BEAT = 60 / BPM, E8 = BEAT / 2, E16 = BEAT / 4;
const DURATION = 6.0;
const NFRAMES = Math.round(DURATION * FPS);
const LOOP_T = NFRAMES / FPS;
const SAFE = { top: 240, bottom: 420, right: 140 };
const HAND = '"Ink Free", "Segoe Print", "Bradley Hand", "Comic Sans MS", "Chalkboard SE", cursive';
const CX = 500;

const ERA_LIST = [[0, 3, () => sceneIdea()], [3, 6, () => sceneHill()]];
const SHOTS = [
  ['idea', 0, 0.0, 3.0, 'a puzzled doodle; a lightbulb is pencilled in, inked, scribbled yellow'],
  ['hill', 1, 3.0, 6.0, 'the bulb becomes the sun over a sketched hill; the hero waves from the top'],
];
const TIMELINE = {
  width: W, height: H, fps: FPS, bpm: BPM, duration: DURATION, frames: NFRAMES, loop: LOOP_T, safe: SAFE,
  format: 'morph-chain',
  shots: SHOTS.map(([key, era, t0, t1, title], i) => ({ id: i + 1, key, era, t0, t1, title })),
  cuts: [],
  morphs: [3.0],
  cues: { draw: 0.5, ink: 1.25, fill: 1.5, pop: 2.0, rays: 3.5, house: 3.5, tree: 3.75, hop1: 4.5, hop2: 5.0 },
  acts: [
    { name: '1 Idea', role: 'build', t0: 0.0, t1: 3.0 },
    { name: '2 Hill', role: 'gift', t0: 3.0, t1: 6.0 },
  ],
  board: [
    { t: 1.75, title: 'the bulb is scribbled in', sound: 'pencil scratches on 16ths', next: 'it lights; the bulb becomes the sun' },
    { t: 5.0, title: 'the sun over the hill', sound: 'warm pad, plucks on the hops', next: 'loops' },
  ],
  narration: [],
};
window.TIMELINE = TIMELINE;
// =====================================================================
//  ERAS, CAMERAS, BRIDGES — sketchbook demo (read by kit/morph.js)
// =====================================================================
const ERA_BG = ['#f2ead8', '#efe3c4'];
function pieceCam(era, t) {
  if (era === 0) return push(t, 1.9, 2.4, { z: 1.2, p: [540, 700], to: [540, 760] });                    // lean in on the idea
  return camMix(camOf({ z: 1.1, p: [540, 760], to: [540, 760] }), CAM0, EZ.io(seg(t, 3.6, 5.2)));     // then pull back to see the world
}
const BRIDGES = [
  { tc: 3.0, A: () => ({ P: bulbPts(BULB.x, BULB.y, BULB.r), c: SK.hilite }), B: () => ({ P: ellipsePts(SUN.x, SUN.y, SUN.r, SUN.r, 0, 64), c: SK.hilite }) },   // the lightbulb -> the sun
];
  // SCORE BODY — sketchbook demo (inside buildScore(); see kit/score-head.js)
  const T = TIMELINE, cu = T.cues;
  to = 'm';
  pad(0.0, 3.1, ['D3', 'A3', 'E4'], 0.03, { type: 'triangle', cut: 900, att: 0.05, rel: 0.2 });
  [['D5', 0], ['Fs5', E16], ['A5', E8]].forEach(([n, dt], i) => pluck(cu.pop + dt, nz(n), 0.22 - i * 0.04, -0.1 + i * 0.1, 0.5, 4200, 0.4));   // the idea lights
  pad(3.0, 6.05, ['D2', 'A2', 'Fs3', 'E4'], 0.045, { cut: 800, att: 0.3, rel: 0.3, send: 0.4 });
  [cu.hop1, cu.hop2].forEach((t, i) => pluck(t, nz(i ? 'A4' : 'Fs4'), 0.2, 0.15, 0.4, 3000, 0.3));                                          // the hops
  to = 's';
  for (let i = 0; i < 12; i++) noiseHit(cu.draw + i * E16, 0.07, 'bandpass', 3600 + (i % 3) * 300, 2, 0.05, -0.2);                      // pencil construction
  for (let i = 0; i < 8; i++) noiseHit(cu.fill + i * E16 / 2, 0.05, 'bandpass', 2600, 1.4, 0.06, 0.1);                                  // the scribble fill
  sweep(2.5, 3.0, 0.012, 500, 2800, 0);                                                                                                 // into the morph
  chime(3.0, [nz('D5'), nz('A5'), nz('E6')], 0.07, 0);                                                                                  // the sun
  for (let i = 0; i < 4; i++) blip(3.75 + i * E8, 2200 + (i % 2) * 400, 1800, 0.03, 0.025, 0.3);                                       // birds
// =====================================================================
//  SCENES — sketchbook demo. World coordinates 1080x1920 (the page); time TT on 2s; ev / popS for events.
// =====================================================================
const BULB = { x: 540, y: 600, r: 120 };
const SUN = { x: 540, y: 500, r: 140 };
// a lightbulb outline: the glass (a circle cut open at the bottom) and a neck, as one closed loop
function bulbPts(x, y, r) {
  const P = [], a0 = Math.PI / 2 - 0.6, a1 = Math.PI / 2 + 0.6 - TAU;
  for (let i = 0; i <= 36; i++) { const a = lerp(a0, a1, i / 36); P.push([x + Math.cos(a) * r, y + Math.sin(a) * r]); }
  P.push([x - 0.36 * r, y + 1.12 * r], [x - 0.34 * r, y + 1.42 * r], [x + 0.34 * r, y + 1.42 * r], [x + 0.36 * r, y + 1.12 * r]);
  return P;
}
// background life: a tiny ant walking a pencil line (legs on 2s)
function ant(x, y, s, key) {
  for (let i = 0; i < 3; i++) { ctx.fillStyle = SK.ink; ctx.beginPath(); ctx.ellipse(x + (i - 1) * 11 * s, y - 6 * s, (i === 1 ? 5 : 6.5) * s, 5 * s, 0, 0, TAU); ctx.fill(); }
  const k = B % 2 ? 1 : -1;
  for (let i = 0; i < 3; i++) gline([[x + (i - 1) * 8 * s, y - 4 * s], [x + (i - 1) * 8 * s + k * (i % 2 ? 5 : -5) * s, y + 3 * s]], { w: 1.8 * s, key: key + i, amp: 0.3, second: false, step: 4 });
  gline([[x + 16 * s, y - 8 * s], [x + 24 * s, y - 16 * s]], { w: 1.6 * s, key: key + 'ant', amp: 0.3, second: false, step: 4 });
}
// background life: a paper plane looping a figure-eight in the top-right margin, its graphite trail behind it
function marginPlane(key) {
  const at = (p) => [830 + 120 * Math.sin(TAU * p), 410 + 55 * Math.sin(2 * TAU * p)];
  const p = TT / 3, trail = [];
  for (let i = 0; i <= 24; i++) trail.push(at(p - 0.35 + 0.35 * i / 24));
  ctx.save(); ctx.setLineDash([10, 12]); gpencil(trail, { key: key + 'tr', w: 2.2, a: 0.6, passes: 1, amp: 1 }); ctx.restore();
  const [x, y] = at(p), [x2, y2] = at(p + 0.01);
  paperPlane(x, y, Math.atan2(y2 - y, x2 - x), 1.25, key);
}

// ---- era 0: the idea
function sceneIdea() {
  const cu = TIMELINE.cues;
  sketchPage({ grid: 'dots' });
  // the ground line the hero stands on, and an ant walking it
  gpencil([[110, 1202], [420, 1196], [700, 1204], [960, 1198]], { key: 'ground', w: 3, a: 0.75 });
  ant(560 + 110 * TT, 1199, 1.5, 'ant');
  // margin stars that twinkle on 2s
  [[110, 560, 0], [170, 760, 1], [96, 930, 2]].forEach(([x, y, i]) => doodleStar(x, y, 24 + 7 * ((B + i) % 3 === 0), 'mstar' + i, { w: 3.4 }));
  marginPlane('mp');
  // the bulb: pencil construction, then ink, then a yellow scribble; it lights on the beat
  const P = bulbPts(BULB.x, BULB.y, BULB.r), lit = ev(cu.pop, 0.25);
  if (lit > 0) {
    for (let i = 0; i < 12; i++) {
      const a = i / 12 * TAU - Math.PI / 2, r0 = BULB.r * 1.25, r1 = BULB.r * (1.5 + 0.12 * ((B + i) % 2));
      if (Math.sin(a) > 0.7) continue;   // not through the neck
      gline([[BULB.x + Math.cos(a) * r0, BULB.y + Math.sin(a) * r0], [BULB.x + Math.cos(a) * r1, BULB.y + Math.sin(a) * r1]], { w: 5, key: 'ray' + i, part: lit, second: false, amp: 0.8, step: 8 });
    }
  }
  scribbleFill(P, SK.hilite, { key: 'bulbfill', part: ev(cu.fill, 0.5), gap: 12, w: 4.5, a: 0.95, base: 0.35 });
  gpencil(P, { closed: true, key: 'bulbc', w: 2.6, a: 0.7, part: ev(cu.draw, cu.ink - cu.draw) });
  gline(P, { closed: true, key: 'bulb', w: 6, part: ev(cu.ink, 0.3) });
  for (let i = 0; i < 3; i++) gline([[BULB.x - 0.4 * BULB.r, BULB.y + (1.2 + i * 0.1) * BULB.r], [BULB.x + 0.4 * BULB.r, BULB.y + (1.17 + i * 0.1) * BULB.r]], { w: 4, key: 'screw' + i, second: false, part: ev(cu.ink + 0.15 + i * 0.04, 0.1) });
