  ctx.restore();
}
function checkMark(x, y, s, part, col = SK.green, key = 'chk') {
  ctx.save(); ctx.translate(x, y); ctx.scale(s, s);
  gline([[-30, 2], [-8, 26], [38, -30]], { w: 12, col, key, amp: 1.2, part, step: 8 });
  ctx.restore();
