// =====================================================================
//  ERAS, CAMERAS, BRIDGES — RI5 #001 (read by kit/morph.js)
// =====================================================================
const ERA_BG = ['#f2ead8', '#f2ead8', '#f2ead8'];
function pieceCam(era, t) {
  if (era === 0) return push(t, TIMELINE.cues.lean, 4.75, { z: 1.8, p: SORE0, to: [540, 900] });             // lean in on the sore knee
  if (era === 1) {
    if (t < 13.25) return camMix(camOf({ z: 1.6, p: SORE1, to: [540, 900] }), CAM0, EZ.io(seg(t, 5.0, 6.25)));   // open out of the knee ring
    return push(t, 13.25, 13.9, { z: 1.45, p: HERO1, to: [540, 1000] });                                          // lean in on the hero
  }
  return null;
}
const BRIDGES = [
  { tc: 5.0, d: 0.5, A: () => ({ P: loopPts(SORE0[0], SORE0[1], 58, 58, 0, 0, 64), c: SK.paper }), B: () => ({ P: loopPts(SORE1[0], SORE1[1], 70, 70, 0, 0, 64), c: SK.paper }) },   // the sore-knee ring -> the X-ray knee ring
  { tc: 14.0, d: 0.5, A: () => SP(HERO1[0], HERO1[1], 75, 0), B: () => SP(HERO2[0], HERO2[1], 110, 0) },                                                                           // the hero -> the hero
];

