input.content:
// =====================================================================
//  SCENES — RI5 #001. World coordinates 1080x1920 (the page); time TT on 2s; ev / popS for events.
//  Facts on screen (review.json, Saraee et al. 2026): 22 elite players (p. 3), 7 angles, 0 of 7 different and
//  the biggest gap under 1 degree (Table 3, p. 6). The ending is the review's bottom line.
// =====================================================================
const HERO2 = [330, 1040];                       // the hero in eras 0 and 2 (same spot: the end is the start, changed)
const SORE0 = [HERO2[0] + 0.34 * 110, HERO2[1] + 1.13 * 110];   // its right knee
const HERO1 = [800, 1160];
const LEGX = [250, 430], HIPY = 560, KNEEY = 880, ANKY = 1150;
const SORE1 = [LEGX[0] + 6, KNEEY];
const CLOUD = [660, 645];

// ---- small drawings
function cloudPts(cx, cy, rx, ry) {
  const P = []; for (let i = 0; i < 72; i++) { const a = i / 72 * TAU, k = 1 + 0.09 * Math.abs(Math.sin(4.5 * a)); P.push([cx + rx * k * Math.cos(a), cy + ry * k * Math.sin(a)]); }
  return P;
}
function thought(cx, cy, part, key, from) {      // a thought bubble: two dots rising from the hero, then the cloud
  const d1 = [from[0] + 130, from[1] - 150], d2 = [from[0] + 200, from[1] - 230];
  [[d1, 14, 0], [d2, 22, 0.2]].forEach(([p, r, o], i) => { const k = seg(part, o, o + 0.3); if (k > 0) gline(loopPts(p[0], p[1], r * EZ.back(k), r * EZ.back(k), 0.1), { w: 3.5, key: key + 'd' + i, second: false }); });
  const C = cloudPts(cx, cy, 210, 150), k = seg(part, 0.35, 1);
  if (k > 0) { gfill(C, SK.sheet, { off: [0, 0], key: key + 'f', a: clamp(k * 3) }); gline(C, { closed: true, w: 4.5, key: key + 'o', part: k }); }
}
function zaps(x, y, r, key, a = 1) {             // pain: three graphite zigzags around a joint, flickering on 2s
  for (let i = 0; i < 3; i++) {
    if ((B + i) % 3 === 0) continue;
    const an = -0.4 + i * 0.9, c = Math.cos(an), s = Math.sin(an), r0 = r * 1.1, r1 = r * 1.75;
    const P = [0, 1, 2, 3].map((j) => { const rr = lerp(r0, r1, j / 3), o = (j % 2 ? 1 : -1) * 9; return [x + c * rr - s * o, y + s * rr + c * o]; });
    gpencil(P, { key: key + i, w: 3.2, a: 0.85 * a, passes: 1, amp: 0.6 });
  }
}
function ant(x, y, s, key) {
  for (let i = 0; i < 3; i++) { ctx.fillStyle = SK.ink; ctx.beginPath(); ctx.ellipse(x + (i - 1) * 11 * s, y - 6 * s, (i === 1 ? 5 : 6.5) * s, 5 * s, 0, 0, TAU); ctx.fill(); }
  const k = B % 2 ? 1 : -1;
  for (let i = 0; i < 3; i++) gline([[x + (i - 1) * 8 * s, y - 4 * s], [x + (i - 1) * 8 * s + k * (i % 2 ? 5 : -5) * s, y + 3 * s]], { w: 1.8 * s, key: key + i, amp: 0.3, second: false, step: 4 });
}
function marginStars(key) { [[110, 560, 0], [160, 760, 1], [96, 930, 2]].forEach(([x, y, i]) => doodleStar(x, y, 24 + 7 * ((B + i) % 3 === 0), key + i, { w: 3.4 })); }
function ground(key) { gpencil([[110, 1202], [420, 1196], [700, 1204], [960, 1198]], { key, w: 3, a: 0.75 }); }
function srcLine(t) {
  const f = () => handLetter('Saraee et al. 2026  ·  one study, 22 players', CX, 1492, 40, { col: SK.graph, reveal: ev(t, 0.6), key: 'src', jit: 0.6 });
  if (DEFER) DEFER.push(f); else f();
}

// ---- era 0: the hunch. One knee hurts; the hero pictures a knock-kneed leg.
function sceneHunch() {
  const cu = TIMELINE.cues;
  sketchPage({ grid: 'dots' });
  ground('g0'); ant(620 + 60 * TT, 1199, 1.5, 'ant0'); marginStars('ms0');
  thought(CLOUD[0], CLOUD[1], ev(cu.bubble, 0.6), 'th0', HERO2);
  // inside the bubble: two legs bending in at the knees, provisional, in graphite
  const lp = ev(cu.legs, 0.9);
  if (lp > 0) {
    ctx.save(); ctx.setLineDash([12, 10]);
    gpencil([[CLOUD[0] - 60, 545], [CLOUD[0] - 22, 645], [CLOUD[0] - 62, 745]], { key: 'kl', w: 4, a: 0.9, part: lp });
    gpencil([[CLOUD[0] + 40, 545], [CLOUD[0] + 2, 645], [CLOUD[0] + 42, 745]], { key: 'kr', w: 4, a: 0.9, part: lp });
    ctx.restore();
  }
  if (TT >= cu.q) handLetter('?', CLOUD[0] + 130, 625 + 6 * Math.sin(B * 0.9), 100, { face: 'marker', col: SK.ink, key: 'q0', reveal: ev(cu.q, 0.1) });
  // the hero, puzzled, looking up at the thought; its right knee hurts
  doodleHero(HERO2[0], HERO2[1], 110, { key: 'hero', legs: true, mood: 'puzzled', look: [0.7, -0.8], arms: [-0.9, 0.6] });
  zaps(SORE0[0], SORE0[1], 30, 'z0');
  for (let i = 0; i < 2; i++) sweat(HERO2[0] - 80 - i * 14, HERO2[1] - 70 + i * 8, ((TT * 1.3 + i * 0.5) % 1), 'sw' + i);
  // the ring around the sore knee (the bridge object), drawn as the camera leans in
  gline(loopPts(SORE0[0], SORE0[1], 58, 58, 0.08), { key: 'ring0', w: 4, col: SK.graph, part: ev(cu.lean - 0.25, 0.5), second: false });
  pageTag("jumper's knee");
  pageCaption(['one knee hurts.', 'is the leg built wrong?'], [[1, 'built wrong']], { size: 72 });
}

// ---- era 1: the check. Both legs, 7 angles, each about the same. Silence. SAME.
function legDraw(x, key, part) {
  const hip = [x, HIPY], knee = [x + 6, KNEEY], ank = [x - 4, ANKY];
  gline(loopPts(hip[0], hip[1], 34, 34, 0.08), { key: key + 'hip', w: 5, part: seg(part, 0, 0.3) });
  gline([hip, knee], { key: key + 'fem', w: 10, part: seg(part, 0.15, 0.55), second: false });
  gline([knee, ank], { key: key + 'tib', w: 10, part: seg(part, 0.5, 0.9), second: false });
  gline(loopPts(knee[0], knee[1], 26, 26, 0.08), { key: key + 'kn', w: 5, part: seg(part, 0.45, 0.65) });
  gline([[ank[0] - 10, ank[1] + 8], [ank[0] + 70, ank[1] + 14]], { key: key + 'ft', w: 9, part: seg(part, 0.85, 1), second: false });
  return { hip, knee, ank };
}
function angleArc(p, key, k) {                   // a graphite protractor arc that flicks on and off at a joint
  if (k <= 0 || k >= 1) return;
  const a = Math.sin(Math.PI * k);
  gpencil(arcPts(p[0], p[1], 62, -Math.PI * 0.95, -Math.PI * 0.05, 14), { key: key, w: 3, a: 0.9 * a, passes: 1 });
  for (let i = 0; i < 5; i++) { const an = -Math.PI * (0.15 + i * 0.175); gpencil([[p[0] + Math.cos(an) * 52, p[1] + Math.sin(an) * 52], [p[0] + Math.cos(an) * 64, p[1] + Math.sin(an) * 64]], { key: key + 't' + i, w: 2.4, a: 0.9 * a, passes: 1 }); }
}
function sceneCheck() {
  const cu = TIMELINE.cues;
  sketchPage({ grid: 'dots' });
  marginStars('ms1');
  const lp = ev(cu.legsDraw, 1.0), L = LEGX.map((x, i) => legDraw(x, 'leg' + i, i === 0 ? 1 : lp));
  gline(loopPts(SORE1[0], SORE1[1], 70, 70, 0.08), { key: 'ring1', w: 4, col: SK.graph, second: false, a: 1 - ev(6.0, 0.5) });
  if (TT < cu.stamp) zaps(SORE1[0], SORE1[1], 34, 'z1', 1 - ev(cu.hush, 1));
  handLetter('sore', LEGX[0], 1232, 52, { key: 'lsore', reveal: ev(cu.legsDraw + 0.4, 0.3) });
  handLetter('pain-free', LEGX[1] + 10, 1232, 52, { key: 'lfine', reveal: ev(cu.legsDraw + 0.8, 0.3) });
  // the checklist: 7 angles, each ticks "about the same" on the beat
  const cp = ev(cu.legsDraw + 0.5, 0.6);
  if (cp > 0) {
    const box = sketchBox(555, 470, 380, 620, 14);
    gfill(box, SK.sheet, { off: [5, 5], key: 'card', a: clamp(cp * 3) });
    gline(box, { closed: true, key: 'cardo', w: 4.5, part: cp });
    handLetter('7 angles', 745, 548, 56, { face: 'marker', key: 'ctitle', reveal: seg(cp, 0.5, 1) });
  }
  const joint = [1, 1, 1, 1, 1, 2, 2];             // the 7 angles sit at the knee (5) and the ankle (2)
  for (let i = 0; i < 7; i++) {
    const y = 625 + i * 66, t = cu.ticks0 + i * cu.tick;
    if (cp >= 1) handLetter('angle ' + (i + 1), 585, y, 42, { col: SK.graph, align: 'left', key: 'row' + i, reveal: ev(cu.legsDraw + 1.1 + i * 0.06, 0.2) });
    if (TT >= t) { handLetter('≈', 815, y + 2, 54, { key: 'eq' + i, reveal: ev(t, 0.1) }); checkMark(882, y - 14, 0.55, ev(t + 0.1, 0.15), SK.green, 'chk' + i); }
    const k = ev(t - 0.1, 0.5);
    L.forEach((l, j) => angleArc(joint[i] === 1 ? l.knee : l.ank, 'arc' + i + j, k));
  }
  // the hero watches the list, goes quiet in the hush, then the stamp
  const after = TT >= cu.stamp, jolt = Math.sin(Math.PI * ev(cu.stamp, 0.25));
  doodleHero(HERO1[0], HERO1[1] - 40 * jolt, 70, { key: 'hero', legs: true, mood: after ? 'wow' : (TT >= cu.hush ? 'puzzled' : 'calm'), look: after ? [-0.9, -0.6] : [-0.5, -1], arms: after ? [1.2, 1.3] : [-0.9, -0.9] });
  if (after) handLetter('!', HERO1[0] + 70, HERO1[1] - 110 - 20 * jolt, 90, { face: 'marker', key: 'bang1', reveal: ev(cu.stamp, 0.08) });
  if (after) {
    const k = ev(cu.stamp, 0.12);
    inkStamp('SAME', 560, 830, lerp(1.9, 1.05, EZ.o3(k)), -0.12, clamp(k * 3), 'same');
  }
  pageTag('the check');
  if (TT < cu.cap2) pageCaption(['22 elite players.', '7 angles, both legs.'], [[1, '7 angles']], { size: 74 });
  else pageCaption(['0 of 7 different.', 'biggest gap < 1°'], [[0, '0 of 7']], { size: 76, at: cu.cap2 - 5.0 });
}

// ---- era 2: so what? Count the jumps; back to the opening, the pain gone, the tally in the bubble.
function sceneSoWhat() {
  const cu = TIMELINE.cues;
  sketchPage({ grid: 'dots' });
  ground('g2'); ant(260 + 50 * (TT - 14), 1199, 1.5, 'ant2'); marginStars('ms2');
  for (let i = 0; i < 2; i++) doodleBird(1000 - 70 * (TT - 14) + i * 64, 420 + i * 30, 1.2 - i * 0.2, (B + i) % 2, 'bird' + i);
  const home = TT >= cu.home;
  if (home) thought(CLOUD[0], CLOUD[1], ev(cu.home, 0.6), 'th2', HERO2);
  // the jumps: up, land, squash; a tally mark inked on every landing
  let hop = 0, sq = 0;
  for (let i = 0; i < cu.jumps; i++) {
    const tj = cu.jump0 + i * 0.5, land = tj + 0.32;
    hop = Math.max(hop, Math.sin(Math.PI * ev(tj, 0.32)));
    sq = Math.max(sq, Math.sin(Math.PI * ev(land, 0.16)));
    const g = Math.floor(i / 5), j = i % 5, x0 = 545 + g * 190, mp = ev(land, 0.12);
    if (j < 4) gline([[x0 + j * 36, 590], [x0 + j * 36 + 3, 705]], { key: 'tal' + i, w: 7, part: mp, second: false });
    else gline([[x0 - 18, 690], [x0 + 128, 605]], { key: 'tal' + i, w: 7, part: mp, second: false });
