  let hop = 0, sq = 0;
  for (let i = 0; i < cu.jumps; i++) {
    const tj = cu.jump0 + i * 0.5, land = tj + 0.32;
    hop = Math.max(hop, Math.sin(Math.PI * ev(tj, 0.32)));
    sq = Math.max(sq, Math.sin(Math.PI * ev(land, 0.16)));
    const g = Math.floor(i / 5), j = i % 5, x0 = 545 + g * 190, mp = ev(land, 0.12);
