  if (TT < cu.stamp) zaps(SORE1[0], SORE1[1], 34, 'z1', 1 - ev(cu.hush, 1));
  handLetter('sore', LEGX[0], 1232, 52, { key: 'lsore', reveal: ev(cu.legsDraw + 0.4, 0.3) });
  handLetter('pain-free', LEGX[1] + 10, 1232, 52, { key: 'lfine', reveal: ev(cu.legsDraw + 0.8, 0.3) });
  // the checklist: 7 angles, each ticks "about the same" on the beat
  const cp = ev(cu.legsDraw + 0.5, 0.6);
  if (cp > 0) {
    const box = sketchBox(555, 470, 380, 620, 14);
    gfill(box, SK.sheet, { off: [5, 5], key: 'card', a: clamp(cp * 3) });
    gline(box, { closed: true, key: 'cardo', w: 4.5, part: cp });
    handLetter('7 angles', 745, 548, 56, { face: 'marker', key: 'ctitle', reveal: seg(cp, 0.5, 1) });
  }
  const joint = [1, 1, 1, 1, 1, 2, 2];             // the 7 angles sit at the knee (5) and the ankle (2)
  for (let i = 0; i < 7; i++) {
    const y = 625 + i * 66, t = cu.ticks0 + i * cu.tick;
    if (cp >= 1) handLetter('angle ' + (i + 1), 585, y, 42, { col: SK.graph, align: 'left', key: 'row' + i, reveal: ev(cu.legsDraw + 1.1 + i * 0.06, 0.2) });
    if (TT >= t) { handLetter('≈', 815, y + 2, 54, { key: 'eq' + i, reveal: ev(t, 0.1) }); checkMark(882, y - 14, 0.55, ev(t + 0.1, 0.15), SK.green, 'chk' + i); }
    const k = ev(t - 0.1, 0.5);
    L.forEach((l, j) => angleArc(joint[i] === 1 ? l.knee : l.ank, 'arc' + i + j, k));
  }
  // the hero watches the list, goes quiet in the hush, then the stamp
  const after = TT >= cu.stamp, jolt = Math.sin(Math.PI * ev(cu.stamp, 0.25));
  doodleHero(HERO1[0], HERO1[1] - 40 * jolt, 70, { key: 'hero', legs: true, mood: after ? 'wow' : (TT >= cu.hush ? 'puzzled' : 'calm'), look: after ? [-0.9, -0.6] : [-0.5, -1], arms: after ? [1.2, 1.3] : [-0.9, -0.9] });
  if (after) handLetter('!', HERO1[0] + 70, HERO1[1] - 110 - 20 * jolt, 90, { face: 'marker', key: 'bang1', reveal: ev(cu.stamp, 0.08) });
  if (after) {
    const k = ev(cu.stamp, 0.12);
    inkStamp('SAME', 560, 830, lerp(1.9, 1.05, EZ.o3(k)), -0.12, clamp(k * 3), 'same');
