  else pageCaption(['0 of 7 different.', 'biggest gap < 1°'], [[0, '0 of 7']], { size: 76, at: cu.cap2 - 5.0 });
}

// ---- era 2: so what? Count the jumps; back to the opening, the pain gone, the tally in the bubble.
function sceneSoWhat() {
  const cu = TIMELINE.cues;
  sketchPage({ grid: 'dots' });
  ground('g2'); ant(260 + 50 * (TT - 14), 1199, 1.5, 'ant2'); marginStars('ms2');
  for (let i = 0; i < 2; i++) doodleBird(1000 - 70 * (TT - 14) + i * 64, 420 + i * 30, 1.2 - i * 0.2, (B + i) % 2, 'bird' + i);
  const home = TT >= cu.home;
  if (home) thought(CLOUD[0], CLOUD[1], ev(cu.home, 0.6), 'th2', HERO2);
  // the jumps: up, land, squash; a tally mark inked on every landing
  let hop = 0, sq = 0;
  for (let i = 0; i < cu.jumps; i++) {
    const tj = cu.jump0 + i * 0.5, land = tj + 0.32;
    hop = Math.max(hop, Math.sin(Math.PI * ev(tj, 0.32)));
    sq = Math.max(sq, Math.sin(Math.PI * ev(land, 0.16)));
    const g = Math.floor(i / 5), j = i % 5, x0 = 545 + g * 190, mp = ev(land, 0.12);
    if (j < 4) gline([[x0 + j * 36, 590], [x0 + j * 36 + 3, 705]], { key: 'tal' + i, w: 7, part: mp, second: false });
    else gline([[x0 - 18, 690], [x0 + 128, 605]], { key: 'tal' + i, w: 7, part: mp, second: false });
    if (sq > 0 && ev(land, 0.16) > 0 && ev(land, 0.16) < 1) for (let s = 0; s < 2; s++) gline([[HERO2[0] - 70 + s * 140, 1200], [HERO2[0] - 84 + s * 168, 1212]], { w: 3, key: 'dust' + i + s, second: false });
  }
  handLetter('jumps', CLOUD[0] + 10, 785, 50, { col: SK.graph, key: 'jlab', reveal: ev(cu.jump0 + 0.4, 0.3) });
  doodleHero(HERO2[0], HERO2[1] - 130 * hop, 110, { key: 'hero', legs: true, mood: home ? 'happy' : 'calm', look: [0.8, -0.7], sx: 1 + 0.12 * sq - 0.05 * hop, sy: 1 - 0.12 * sq + 0.06 * hop, arms: hop > 0.2 ? [1.3, 1.3] : [-0.9, 0.6] });
  if (home) sparkle(SORE0[0] + 20, SORE0[1] - 10, 34, ev(cu.home + 0.3, 0.6), 'kspk');
  pageTag('so what?');
  if (TT < cu.cap4) pageCaption(['count the jumps.', 'coach the landing.'], [[1, 'landing']], { size: 76, at: 0.6 });
  else pageCaption(['load + landing first.', 'leg shape second.'], [[0, 'first']], { size: 74, at: cu.cap4 - 14.0 });
  if (TT >= cu.src) srcLine(cu.src);
}

