['D5', 'E5', 'Fs5', 'A5', 'B5', 'D6', 'E6'].forEach((n, i) => pluck(cu.ticks0 + i * cu.tick, nz(n), 0.17, -0.3 + i * 0.1, 0.35, 3800, 0.2));   // one per tick, rising
for (let i = 0; i < 9; i++) pluck(cu.cap2 + i * E8 / 1.5, nz(['D5', 'A5', 'Fs5'][i % 3]), 0.1, i % 2 ? 0.3 : -0.3, 0.12, 3000, 0);  // the count: the busiest bar, dry, done by 12.0
// 12.0 to 13.0: silence
pluck(cu.stamp, nz('D4'), 0.55, 0, 0.4, 2400, 0.1); pluck(cu.stamp, nz('A4'), 0.45, -0.1, 0.4, 2400, 0.1); pluck(cu.stamp, nz('Fs5'), 0.35, 0.1, 0.4, 2600, 0.1);   // the stamp: a short chord
sub(cu.stamp, 0.5);
pad(13.15, 14.2, ['D3', 'A3', 'D4'], 0.03, { cut: 700, att: 0.05, rel: 0.3 });                                         // a flat chord after it
pad(14.0, 24.05, ['D2', 'A2', 'Fs3', 'E4'], 0.03, { cut: 800, att: 0.6, rel: 0.4, send: 0.4 });                         // so what: warm, under everything
for (let i = 0; i < cu.jumps; i++) pluck(cu.jump0 + i * 0.5 + 0.32, nz(['Fs4', 'A4', 'D5', 'A4'][i % 4]), 0.13, i % 2 ? 0.2 : -0.2, 0.3, 3000, 0.25);   // the landings
chime(cu.home, [nz('D5'), nz('A5'), nz('E6')], 0.05, 0);                                                                 // home
to = 's';
for (let i = 0; i < 10; i++) noiseHit(cu.legs + i * E16, 0.06, 'bandpass', 3600 + (i % 3) * 300, 2, 0.04, -0.2);      // pencil in the bubble
for (let i = 0; i < 8; i++) noiseHit(cu.legsDraw + i * E16, 0.06, 'bandpass', 3400 + (i % 2) * 400, 2, 0.04, 0.2);     // pencil on the legs
for (let i = 0; i < cu.jumps; i++) noiseHit(cu.jump0 + i * 0.5 + 0.32, 0.05, 'lowpass', 500, 1, 0.08, 0);             // soft landings
for (let i = 0; i < 2; i++) blip(16.0 + i * E8, 2200 + i * 400, 1800, 0.03, 0.02, 0.3);                                 // birds

